1: //! DJI `.txt` flight log binary header parser.
2: //!
3: //! Parses the initial 100-byte or 101-byte fixed binary header containing stream offsets,
4: //! format versions, application ecosystem flags, and cryptographic markers.
5: 
6: use byteorder::{ByteOrder, LittleEndian};
7: 
8: use super::version::{classify_version, Department, VersionCapabilities};
9: use crate::error::FlightReaderError;
10: 
11: /// Parsed fixed binary header from a DJI `.txt` mobile flight record.
12: ///
13: /// Every DJI flight telemetry log commences with either a 100-byte or 101-byte
14: /// header defining stream boundaries and metadata.
15: #[derive(Debug, Clone, PartialEq, Eq)]
16: pub struct TxtHeader {
17:     /// Byte offset where the details summary block (v1–v11) or telemetry records (v12–v14) reside.
18:     pub details_offset: i64,
19:     /// Declared header length in bytes (`100` or `101`).
20:     pub header_length: i16,
21:     /// Format major version number (`1` through `14`).
22:     pub version: u8,
23:     /// DJI ground station application ecosystem identifier.
24:     pub department: Department,
25:     /// Cryptographic status byte (`0` = plaintext, `!= 0` = scrambled / encrypted).
26:     pub scrambled_flag: u8,
27:     /// Reserved compatibility bytes (offsets 13 through 99, 87 bytes total).
28:     pub reserved: [u8; 87],
29:     /// Header padding byte present strictly when `header_length == 101` (offset 100).
30:     pub padding: Option<u8>,
31: }
32: 
33: impl TxtHeader {
34:     /// Minimum byte size required to inspect a standard DJI `.txt` header.
35:     pub const MIN_HEADER_SIZE: usize = 100;
36:     /// Extended byte size for modern headers containing an extra padding byte.
37:     pub const EXTENDED_HEADER_SIZE: usize = 101;
38: 
39:     /// Parse a fixed binary header from the provided byte slice with zero allocations.
40:     ///
41:     /// # Protocol Specification
42:     /// - Bytes 0..8: `details_offset` (`i64`, Little-Endian)
43:     /// - Bytes 8..10: `header_length` (`i16`, Little-Endian, must be 100 or 101)
44:     /// - Byte 10: `version` (`u8`, must be in `1..=14`)
45:     /// - Byte 11: `department` (`u8` mapped to [`Department`])
46:     /// - Byte 12: `scrambled_flag` (`u8`)
47:     /// - Bytes 13..100: `reserved` (`[u8; 87]`)
48:     /// - Byte 100: `padding` (`Option<u8>`, present only if `header_length == 101`)
49:     ///
50:     /// # Errors
51:     /// - [`FlightReaderError::UnexpectedEof`] if `input.len() < 100`, or `input.len() < 101` when `header_length == 101`.
52:     /// - [`FlightReaderError::InvalidHeaderLength`] if `header_length` is not 100 or 101.
53:     /// - [`FlightReaderError::UnsupportedVersion`] if `version` is not supported (1..=14).
54:     /// - [`FlightReaderError::CorruptedHeader`] if `details_offset < 0`.
55:     pub fn parse(input: &[u8]) -> Result<Self, FlightReaderError> {
56:         if input.len() < Self::MIN_HEADER_SIZE {
57:             return Err(FlightReaderError::UnexpectedEof);
